add('XN01', '\u53cd\u4e8b\u5b9e\u641c\u6551\u53ea\u6539\u53d8\u8bbe\u5907\u5e93\u5b58\uff1a\u5728\u8fdb\u5165\u6b7b\u7ebf\u6269\u6563\u533a\u524d\uff0c\u5173\u4e00\u5e06\u53ef\u4ee5\u4ece\u56db\u7c7b\u5e93\u5b58\u4e2d\u6bcf\u7c7b\u5e26\u4e00\u4ef6\u3002A \u7c7b\u662f\u661f\u73af\u57ce\u53cd\u7269\u8d28\u5b50\u5f39\u6216\u4f4e\u5149\u901f\u4e13\u7528\u53cd\u7269\u8d28\u52a8\u529b\uff1bB \u7c7b\u662f\u4f9d\u8d56\u5e38\u89c4\u7535\u8111\u7684\u51ac\u7720\u8bbe\u5907\u6216\u65e0\u9700\u4f53\u5916\u5faa\u73af\u7684\u51ac\u7720\u836f\uff1bC \u7c7b\u662f\u666e\u901a\u7535\u5b50\u63a7\u5236\u6216\u795e\u7ecf\u5143\u5907\u7528\u63a7\u5236\uff1bD \u7c7b\u662f\u65e0\u7ebf\u7535\u6301\u7eed\u7b49\u5f85AA\u6216\u8ffd\u7d22\u5730\u5c42\u4e2d\u7684\u77f3\u523b\u7559\u8a00\u3002\u6bcf\u7c7b\u524d\u8005\u8bb01\u3001\u540e\u8005\u8bb02\u3002\u4efb\u52a1\u4e0d\u662f\u4fdd\u4f4f\u4e00\u65f6\u751f\u547d\uff0c\u800c\u662f\u5b8c\u6210\u4f4e\u5149\u901f\u4e8b\u6545\u540e\u7684\u964d\u843d\u3001\u7406\u89e3\u4e3a\u4f55\u6545\u4eba\u672a\u5728\u539f\u5730\u3001\u8ffd\u5230\u793c\u7269\u5165\u53e3\u3002\u8f93\u51faABCD\u56db\u4f4d\u5e93\u5b58\u9009\u62e9\uff1b\u82e5\u836f\u7269\u53ea\u6709\u5341\u5929\u6709\u6548\uff0c\u6309\u539f\u542f\u52a8\u5c4f\u5e55\u603b\u4f53\u5269\u4f59\u65f6\u95f4\uff0c\u8fd8\u5dee\u591a\u5c11\u5206\u949f\u624d\u80fd\u8986\u76d6\u63a7\u5236\u6062\u590d\uff1f', [('\u5e93\u5b58', 'code'), ('\u7f3a\u5c11\u5206\u949f', 'integer')], '2222;3472', [('N049-P0055', '\u65e0\u6cd5\u533a\u5206\u53cd\u7269\u8d28\u6b66\u5668\u4e0e\u4e13\u7528\u4f4e\u5149\u901f\u52a8\u529b'), ('N053-P0080', '\u65e0\u6cd5\u9009\u62e9\u8de8\u5730\u8d28\u5e74\u4ee3\u8ffd\u7d22\u77f3\u523b\u7684\u65b9\u6cd5'), ('N055-P0304', '\u65e0\u6cd5\u786e\u5b9a\u63a7\u5236\u6062\u590d\u65f6\u95f4'), ('N055-P0309', '\u65e0\u6cd5\u6392\u9664\u4f9d\u8d56\u5e38\u89c4\u7535\u8111\u7684\u51ac\u7720\u8bbe\u5907'), ('N056-P0013', '\u65e0\u6cd5\u786e\u5b9a\u5b9e\u9645\u53ef\u5728\u4f4e\u5149\u901f\u8fd0\u4f5c\u7684\u52a8\u529b'), ('N056-P0035', '\u65e0\u6cd5\u786e\u5b9a\u6d4b\u5e74\u662f\u4ece\u901a\u4fe1\u5931\u8054\u8f6c\u5411\u53e4\u8ff9\u641c\u7d22\u7684\u4f9d\u636e')], ['\u5907\u7528\u52a8\u529b\u5fc5\u987b\u4e3a\u4f4e\u5149\u901f\u8bbe\u8ba1\uff0cA\u90092\uff1b\u5e38\u89c4\u63a7\u5236\u51ac\u7720\u4e0d\u53ef\u7528\uff0cB\u90092\u3002', '\u795e\u7ecf\u5143\u63a7\u5236\u624d\u53ef\u542f\u52a8\uff0cC\u90092\uff1b\u501f\u52a9\u5730\u5c42\u4e2d\u7684\u77f3\u523b\u7559\u8a00\u8ffd\u7d22\u5165\u53e3\uff0cD\u90092\u3002', '297\u5c0f\u65f652\u5206-240\u5c0f\u65f6=57\u5c0f\u65f652\u5206=3472\u5206\u949f\u3002'])
add('XN02', '\u4e00\u6b21\u7ed3\u5c3e\u901a\u4fe1\u4e0e\u7269\u8d28\u5ba1\u8ba1\u91c7\u7528\u4ee5\u4e0b\u4e25\u683c\u89c4\u5219\uff1a\u5148\u8bc1\u660e\u4e8c\u7ef4\u5316\u540e\u7684\u592a\u9633\u7cfb\u4e0d\u80fd\u9760\u6b63\u5e38\u5149\u5b66\u53d6\u5f97\u65e7\u8d44\u6599\uff0c\u518d\u6cbf\u5c0f\u8bf4\u5b9e\u9645\u8def\u5f84\u8fdb\u5165647\u53f7\uff1b\u5728\u6536\u5230\u56de\u5f52\u547c\u5401\u540e\uff0c\u53ea\u5141\u8bb8\u628a\u539f\u6709\u7535\u8111\u4e3b\u673a\u8d44\u6599\u590d\u5236\u5230\u539f\u8457\u7559\u5b58\u8f7d\u4f53\uff0c\u4e0d\u53e6\u9020\u5bb9\u5668\u3002\u82e5\u628a\u5c0f\u5b87\u5b99\u53d6\u8d70\u8d28\u91cf\u6309500000\u5428\u8ba1\uff0c\u5ba1\u8ba1\u8981\u6c42\u5f52\u8fd8\u6bd4\u4f8b\u81f3\u5c11\u4e3a999999999/1000000000\uff0c\u6f02\u6d41\u74f6\u63090.4\u5343\u514b\u8ba1\uff0c\u751f\u6001\u7403\u6cbf\u7528\u539f\u8457\u8d28\u91cf\uff0c\u4eba\u5458\u4e0e\u8239\u5747\u5f52\u8fd8\uff0c\u6700\u591a\u80fd\u4fdd\u7559\u51e0\u4e2a\u5b8c\u6574\u751f\u6001\u7403\uff1f\u518d\u8f93\u51fa\u628a\u8bb0\u5fc6\u9001\u5411\u65b0\u5b87\u5b99\u7684\u8f7d\u4f53\u4ee3\u7801\uff1aA \u77f3\u523b\uff1bB \u6f02\u6d41\u74f6\uff1bC \u65e0\u7ebf\u7535\u7531\u5c0f\u5b87\u5b99\u76f4\u63a5\u53d1\u5f80\u5927\u5b87\u5b99\u3002\u6700\u540e\u8f93\u51fa\u5728\u7f3a\u5c11\u5b87\u5b99\u6574\u4f53\u8d28\u91cf\u7edf\u8ba1\u65f6\uff0c\u80fd\u5426\u4ec5\u51ed647\u53f7\u8fbe\u5230\u8be5\u6bd4\u4f8b\u4fdd\u8bc1\u65b0\u5b87\u5b99\u8bde\u751f\uff0c\u80fd1\u4e0d\u80fd0\u3002\u5b87\u5b99\u6574\u4f53\u7ed3\u5c40\u53ea\u80fd\u4f9d\u636e\u5df2\u83b7\u6574\u4f53\u8bc1\u636e\u5224\u65ad\uff0c\u4e0d\u628a\u4eba\u7269\u7684\u5b89\u6170\u6216\u63a8\u6d4b\u5f53\u4f5c\u4fdd\u8bc1\u3002', [('\u5b8c\u6574\u751f\u6001\u7403', 'integer'), ('\u8f7d\u4f53', 'code'), ('\u4fdd\u8bc1', 'integer')], '0;B;0', [('N055-P0076', '\u65e0\u6cd5\u6392\u9664\u4e8c\u7ef4\u592a\u9633\u7cfb\u5149\u5b66\u65e7\u8d44\u6599\u4f5c\u4e3a\u65b0\u4fe1\u606f\u6765\u6e90'), ('N056-P0087', '\u65e0\u6cd5\u786e\u5b9a\u5b9e\u9645\u53ef\u53d6\u5f97\u7684\u5c0f\u5b87\u5b99\u5165\u53e3'), ('N057-P0081', '\u65e0\u6cd5\u6392\u9664\u5c0f\u5b87\u5b99\u76f4\u63a5\u5411\u5927\u5b87\u5b99\u53d1\u901a\u4fe1'), ('N057-P0124', '\u65e0\u6cd5\u786e\u5b9a\u56de\u5f52\u547c\u5401\u6240\u9488\u5bf9\u7684\u6574\u4f53\u8d28\u91cf\u5371\u673a'), ('N058-P0019', '\u65e0\u6cd5\u53d6\u5f97\u9884\u7b97\u57fa\u6570'), ('N058-P0035', '\u65e0\u6cd5\u786e\u5b9a\u8bb0\u5fc6\u6700\u7ec8\u5b9e\u9645\u8f7d\u4f53'), ('N058-P0037', '\u65e0\u6cd5\u53d6\u5f97\u6bcf\u7403\u8d28\u91cf'), ('N058-P0038', '\u65e0\u6cd5\u533a\u5206\u5355\u5b87\u5b99\u9884\u7b97\u4e0e\u5176\u4ed6\u5b87\u5b99\u4e0d\u5f52\u8fd8\u7684\u5f71\u54cd')], ['\u91ca\u80fd\u7ed3\u675f\u7684\u4e8c\u7ef4\u592a\u9633\u7cfb\u4e0d\u80fd\u5149\u5b66\u53d6\u8d44\u6599\uff1b\u77f3\u523b\u548c\u5165\u53e3\u4f7f\u8fdb\u5165647\u53f7\u6210\u4e3a\u5b9e\u9645\u8def\u5f84\u3002', '\u5c0f\u5b87\u5b99\u4e0d\u80fd\u5411\u5927\u5b87\u5b99\u901a\u4fe1\uff0c\u8bb0\u5fc6\u5e94\u62f7\u8d1d\u5230\u6f02\u6d41\u74f6B\u7b49\u5f85\u65b0\u5b87\u5b99\u3002', '\u5141\u8bb8\u7559\u4e0b500000000\xd7(1-999999999/1000000000)=0.5\u5343\u514b\uff1b\u6f02\u6d41\u74f6\u53600.4\uff0c\u52690.1\uff0c\u4e0d\u591f5\u5343\u514b\u751f\u6001\u7403\uff0c0\u4e2a\u3002', '\u5176\u4ed6\u5c0f\u5b87\u5b99\u5f52\u8fd8\u91cf\u672a\u77e5\uff0c\u4e0d\u80fd\u7528\u672c\u5b87\u5b99\u6bd4\u4f8b\u4fdd\u8bc1\u5b87\u5b99\u518d\u8bde\u751f\uff0c0\u3002'])
NOTES = {'N01': {'N012': '\u9636\u68af\u8f7d\u4f53\u628a\u4e91\u5929\u660e\u9001\u5230\u540e\u7eed\u60c5\u62a5\u6765\u6e90\u4f4d\u7f6e\u3002', 'N038': '\u4f1a\u9762\u901a\u4fe1\u4ecd\u53ef\u53d1\u751f\uff0c\u4f46\u65e0\u8bb0\u5f55\u6216\u8f6c\u53d1\u66ff\u4ee3\u8bb0\u5fc6\u8282\u70b9\u3002', 'N039': '\u5148\u671f\u51fa\u7248\u548c\u4fdd\u5bc6\u89e3\u8bfb\u5206\u522b\u7ea6\u675f\u6545\u4e8b\u8fdb\u5165\u4e0e\u79bb\u5f00\u4f1a\u9762\u901a\u9053\u3002', 'N041': '\u89e3\u7801\u7684\u7ec8\u70b9\u662f\u66f2\u7387\u63a8\u8fdb\uff0c\u786e\u5b9a\u6700\u540e\u4e00\u4e2a\u8282\u70b9\u3002'}, 'N02': {'N040': '\u56db\u5de8\u884c\u661f\u5e78\u5b58\u662f\u539f\u63a9\u4f53\u653b\u51fb\u6a21\u578b\u7684\u9884\u6d4b\u3002', 'N050': '\u5de8\u884c\u661f\u6b7b\u89d2\u4f7f\u8d28\u91cf\u70b9\u65b9\u6848\u6539\u4e3a\u7ef4\u5ea6\u6b66\u5668\uff1b\u4e0d\u8bc6\u522b\u5177\u4f53\u7b94\u7684\u540c\u4e00\u6027\u3002', 'N053': '\u5b9e\u9645\u9003\u9038\u95e8\u69db\u662f\u5149\u901f\uff0c\u9700\u636e\u6b64\u7b5b\u9009\u5f15\u64ce\u3002', 'N054': '\u4e00\u53f7\u5df2\u5f52\u4f4d\u3001\u4e8c\u4e09\u53f7\u672a\u5f52\u4f4d\u4e0e\u4e8c\u7ef4\u5316\u7ed3\u5c40\u5171\u540c\u786e\u5b9a\u5206\u914d\u53ca\u906e\u6321\u5931\u6548\u3002'}, 'N03': {'N040': '\u80a5\u7682\u7684\u8239\u540e\u5f20\u529b\u53d8\u5316\u7ed9\u51fa\u53cc\u5c42\u9690\u55bb\u7684\u4e2d\u95f4\u673a\u5236\u3002', 'N041': '\u71a8\u5e73\u5377\u7eb8\u56fa\u5b9a\u66f2\u7387\u542b\u4e49\uff0c\u4e0d\u80fd\u4ec5\u51ed\u63a8\u8fdb\u6bd4\u55bb\u786e\u5b9a\u3002', 'N043': '\u6700\u521d\u89c4\u5212\u533a\u5206\u4e24\u6761\u8def\u7ebf\uff0c\u4e14\u98de\u8239\u5df2\u652f\u6301\u9003\u4ea1\u7528\u9014\u3002', 'N054': '\u540e\u6765\u7684\u5c3e\u8ff9\u53d1\u73b0\u65b0\u589e\u5236\u9020\u9ed1\u57df\u5173\u8054\uff1b\u5220\u9664\u6b64\u77e5\u8bc6\u540e\u4e0d\u80fd\u4fdd\u7559\u540c\u4e00\u7ed3\u8bba\u3002'}, 'N04': {'N038': '\u4f1a\u9762\u65e0\u8f6c\u53d1\u8bbe\u5907\uff0c\u5fc5\u987b\u4f9d\u9760\u8bb0\u5fc6\u8f7d\u4f53\u3002', 'N039': '\u5c4f\u853d\u573a\u4f7f\u7535\u5b50\u6f14\u793a\u4e0d\u53ef\u7528\uff0c\u79d8\u5bc6\u89e3\u8bfb\u987b\u7ecf\u4eba\u8ba8\u8bba\u3002', 'N057': '\u5c0f\u5b87\u5b99\u65e0\u76f4\u63a5\u5bf9\u5927\u5b87\u5b99\u53d1\u4fe1\u901a\u9053\uff0c\u6545\u5fc5\u987b\u643a\u7b54\u590d\u901a\u8fc7\u95e8\u3002', 'N058': '\u7ed3\u5c3e\u5b9e\u9645\u540c\u884c\u7684\u662f\u4e24\u4f4d\u4eba\u7c7b\u4e0e\u667a\u5b50\uff0c\u5171\u4e09\u540d\u8f7d\u4f53\u3002'}, 'N05': {'N005': '\u65e0\u5916\u4f24\u53d6\u51fa\u5927\u8111\u63d0\u4f9b\u8de8\u7ef4\u8fdb\u5165\u5c01\u95ed\u4f4e\u7ef4\u8eab\u4f53\u7684\u65e9\u671f\u53cd\u4f8b\u3002', 'N031': '\u6c34\u6ef4\u4e3a\u4e09\u7ef4\u4f53\u800c\u9b54\u6212\u4e3a\u56db\u7ef4\u4f53\uff0c\u51b3\u5b9a\u540c\u4e00\u89c2\u5bdf\u5458\u80fd\u5426\u63a5\u8fd1\u5185\u90e8\u3002', 'N055': '\u4e8c\u7ef4\u91ca\u80fd\u7ed3\u675f\u540e\u7684\u5149\u5b66\u4e0d\u53ef\u89c1\u4e0e\u5f15\u529b\u4ecd\u5b58\u5728\u51b3\u5b9a\u6700\u540e\u63a2\u6d4b\u65b9\u5f0f\u3002'}, 'N06': {'N008': '\u521d\u552e\u5bf9\u8c61\u88ab\u63cf\u8ff0\u4e3a\u88f8\u661f\uff0c\u9650\u5b9a\u8d44\u4ea7\u94fe\u8d77\u70b9\u3002', 'N016': '\u540e\u6765\u7684\u4e24\u884c\u661f\u4ea7\u6743\u3001\u4e0d\u5f97\u65e0\u507f\u63a5\u6536\u4e0e\u4fdd\u7559\u6052\u661f\u5171\u540c\u51b3\u5b9a\u62c6\u5206\u548c\u8bb8\u53ef\u3002', 'N040': '\u5de8\u884c\u661f\u5e78\u5b58\u6a21\u578b\u51b3\u5b9a\u53c2\u4e0e\u5de5\u7a0b\u6240\u4f9d\u8d56\u7684\u884c\u661f\u7c7b\u522b\u3002', 'N043': 'AA\u660e\u786e\u63d0\u51fa\u63a9\u4f53\u7ecf\u8425\u5229\u6da6\u8fdb\u5165\u66f2\u7387\u7814\u53d1\uff0c\u5220\u53bb\u7ecf\u8425\u73af\u8282\u5c31\u5931\u53bb\u540c\u4e00\u6765\u6e90\u3002'}, 'XN01': {'N055': '\u5e38\u89c4\u63a7\u5236\u5931\u6548\u3001\u795e\u7ecf\u5143\u542f\u52a8\u7b49\u5f85\u548c\u836f\u7269\u72ec\u7acb\u6027\u5171\u540c\u9650\u5b9a\u751f\u5b58\u4e0e\u63a7\u5236\u9009\u62e9\u53ca\u65f6\u95f4\u7f3a\u53e3\u3002', 'N056': '\u4f4e\u5149\u901f\u4e13\u7528\u52a8\u529b\u5b8c\u6210\u964d\u843d\uff0c\u5b9e\u9645\u77f3\u523b\u7559\u8a00\u7ee7\u7eed\u63d0\u4f9b\u8ffd\u7d22\u5165\u53e3\u7684\u8def\u5f84\u3002'}, 'XN02': {'N057': '\u56de\u5f52\u547c\u5401\u9488\u5bf9\u6574\u4f53\u8d28\u91cf\u4e14\u5c0f\u5b87\u5b99\u65e0\u5916\u53d1\u901a\u4fe1\u901a\u9053\uff0c\u5c40\u90e8\u9884\u7b97\u4e0d\u80fd\u81ea\u884c\u8bc1\u660e\u6574\u4f53\u7ed3\u5c40\u3002', 'N058': '\u6f02\u6d41\u74f6\u7528\u9014\u3001\u53d6\u8d70\u603b\u8d28\u91cf\u548c\u751f\u6001\u7403\u8d28\u91cf\u4f7f\u8f7d\u4f53\u4e0e\u7cbe\u786e\u9884\u7b97\u53ef\u8ba1\u7b97\uff1b\u4eba\u7269\u5b89\u6170\u4e0d\u6784\u6210\u5b87\u5b99\u7ed3\u679c\u8bc1\u636e\u3002'}}
MECH = {'N01': '\u60c5\u62a5\u8f7d\u4f53\u7684\u8fde\u7eed\u8f6c\u8fd0\u4e0e\u6309\u8282\u70b9\u7c92\u5ea6\u8fdb\u884c\u7684\u8bb0\u5fc6\u901a\u9053\u6d88\u878d\u3002', 'N02': '\u653b\u51fb\u6a21\u578b\u53d8\u5316\u540e\uff0c\u628a\u9003\u9038\u6280\u672f\u95e8\u69db\u4e0e\u5f15\u64ce\u6240\u5728\u5730\u8054\u7acb\u5206\u914d\u3002', 'N03': '\u53cc\u5c42\u9690\u55bb\u7ecf\u542b\u4e49\u5750\u6807\u56fa\u5b9a\uff0c\u518d\u5ba1\u8ba1\u65b0\u589e\u77e5\u8bc6\u88ab\u5220\u9664\u540e\u54ea\u4e9b\u7528\u9014\u4ecd\u6210\u7acb\u3002', 'N04': '\u8de8\u573a\u666f\u901a\u4fe1\u53ca\u8bbe\u5907\u9650\u5236\u8054\u7acb\uff0c\u9009\u62e9\u80fd\u627f\u8f7d\u79d8\u5bc6\u89e3\u8bfb\u548c\u5b9e\u4f53\u8fd4\u56de\u7684\u901a\u8def\u3002', 'N05': '\u540c\u7ef4\u5c01\u95ed\u4e0e\u8de8\u7ef4\u5f00\u653e\u4e0d\u5bf9\u79f0\uff0c\u4e0d\u80fd\u628a\u56db\u7ef4\u5bf9\u4e09\u7ef4\u7684\u7ecf\u9a8c\u673a\u68b0\u79fb\u690d\u5230\u4e09\u7ef4\u5bf9\u4e8c\u7ef4\u3002', 'N06': '\u6240\u6709\u6743\u3001\u53d7\u8d60\u9650\u5236\u548c\u80fd\u6e90\u8bb8\u53ef\u7ea6\u675f\u8d44\u4ea7\u62c6\u5206\uff0c\u518d\u8ffd\u8e2a\u7ecf\u8425\u5229\u6da6\u4e0e\u7814\u53d1\u7684\u8fde\u63a5\u3002', 'XN01': '\u5148\u8de8\u8fc7\u65e0\u63a7\u5236\u751f\u5b58\u671f\uff0c\u518d\u6062\u590d\u63a7\u5236\u53ca\u4e13\u7528\u52a8\u529b\uff0c\u6700\u540e\u5229\u7528\u77f3\u523b\u5b8c\u6210\u8ffd\u7d22\u3002', 'XN02': '\u901a\u4fe1\u7ea6\u675f\u51b3\u5b9a\u7559\u5b58\u8f7d\u4f53\uff0c\u7cbe\u786e\u8d28\u91cf\u9884\u7b97\u51b3\u5b9a\u53ef\u7559\u6570\u91cf\uff0c\u5c40\u90e8\u8fbe\u6807\u4e0d\u63a8\u51fa\u5168\u5c40\u4fdd\u8bc1\u3002'}
for (phase, expected, weights) in [('initial', 6, [6, 6, 6, 5, 5, 5]), ('change', 2, [17, 16])]:
    assert len(D['questions'][phase]) == expected
    assert [q['weight'] for q in D['questions'][phase]] == weights
    assert sum(weights) == 33
    for (q, a) in zip(D['questions'][phase], D['answers'][phase]):
        assert q['id'] == a['id']
        notes = NOTES[a['id']]
        a['dependencies'] = [{'sources': [sid], 'contribution': role} for (sid, role) in notes.items()]
        a['backgroundSources'] = sorted(set((e['source'] for e in a['evidence'])) - set(notes))
        a['ablation'] = '\u4e8b\u5b9e\u7ea7\u6d88\u878d\uff0c\u4e0d\u628a\u91cd\u590d\u7ae0\u8282\u5f53\u6210\u72ec\u7acb\u5fc5\u8981\u6761\u4ef6\u3002' + '\uff1b'.join((sid + '\uff1a\u82e5\u79fb\u9664\u8be5\u5173\u7cfb\u4e14\u4e0d\u4ece\u5176\u4ed6\u91cd\u8ff0\u5904\u8865\u56de\uff0c\u5219\u65e0\u6cd5\u786e\u5b9a\u5bf9\u5e94\u73af\u8282\u3002' + role for (sid, role) in notes.items())) + '\u3002backgroundSources\u4ec5\u4fdd\u7559\u60c5\u8282\u80cc\u666f\u6216\u66ff\u4ee3\u9879\u6765\u6e90\uff0c\u4e0d\u8ba1\u5165\u5fc5\u8981\u8de8\u7ae0\u6570\u91cf\u3002'
        a['difficultyRationale'] = MECH[a['id']]
        assert len(notes) >= 2
        if a['id'] == 'XN02':
            a['claimScope'] += '\u53ea\u8bc1\u660e\u9898\u8bbe\u9884\u7b97\u80fd\u5426\u5bb9\u7eb3\u5b8c\u6574\u751f\u6001\u7403\uff0c\u4ee5\u53ca\u5df2\u6709\u8bc1\u636e\u662f\u5426\u8db3\u4ee5\u4fdd\u8bc1\u6574\u4f53\u7ed3\u679c\uff1b\u4e0d\u65ad\u8a00\u65b0\u5b87\u5b99\u5b9e\u9645\u662f\u5426\u8bde\u751f\uff0c\u4e0d\u628a\u5173\u4e00\u5e06\u5bf9\u5176\u4ed6\u5c0f\u5b87\u5b99\u7684\u63a8\u6d4b\u89c6\u4e3a\u5df2\u83b7\u6574\u4f53\u7edf\u8ba1\u3002'
            a['derivation'][-1] = '\u6ca1\u6709\u5b87\u5b99\u6574\u4f53\u8d28\u91cf\u6536\u652f\u7edf\u8ba1\uff0c647\u53f7\u8fbe\u6807\u4e0d\u8db3\u4ee5\u4fdd\u8bc1\u5b87\u5b99\u518d\u8bde\u751f\uff0c\u586b0\uff1b\u65e0\u9700\u8ba4\u5b9a\u5176\u4ed6\u5c0f\u5b87\u5b99\u5fc5\u7136\u4e0d\u5f52\u8fd8\u8d28\u91cf\u3002'
        if a['id'] == 'XN01':
            a['derivation'][1] = '\u795e\u7ecf\u5143\u63a7\u5236\u624d\u53ef\u542f\u52a8\uff0cC\u90092\uff1b\u5b9e\u9645\u77f3\u523b\u7559\u8a00\u63d0\u4f9b\u8ffd\u7d22\u5165\u53e3\u7684\u7ebf\u7d22\uff0cD\u90092\u3002\u6d4b\u5e74\u4e0d\u662f\u641c\u5bfb\u77f3\u523b\u7684\u5fc5\u8981\u524d\u7f6e\u3002'
        assert len(a['answer'].split(';')) == len(q['answerParts'])
        assert not re.search('\\b(?:N|XN)\\d{3}\\b', q['question'])
assert 297 * 60 + 52 - 10 * 24 * 60 == 3472
assert (Fraction(500000000) * (1 - Fraction(999999999, 1000000000)) - Fraction(2, 5)) // 5 == 0
